from pathlib import Path

import pytesseract
from PIL import Image, ImageOps
from openpyxl import Workbook

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

# Tier priority (lowest numeric rank = highest priority).
TIERS = [
    ("GRAND_TOTAL", ["GRAND TOTAL"]),
    ("TOTAL_RM", ["TOTAL RM", "TOTAL: RM"]),
    ("TOTAL_AMOUNT", ["TOTAL AMOUNT"]),
    ("TOTAL_GENERIC", [
        "TOTAL DUE", "AMOUNT DUE", "BALANCE DUE",
        "NETT TOTAL", "NET TOTAL",
        "TOTAL", "AMOUNT",
    ]),
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL",
    "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
    # not in hint, but clearly non-monetary summary rows
    "QTY", "QUANTITY",
]

# Lines that contain these alongside a tier keyword are tabular column
# headers (precede first line item, not the summary total).
COLUMN_HEADER_TOKENS = [
    "DESCRIPTION", "U.PRICE", "U/PRICE", "UNIT PRICE",
    "U/(RM)", "U(RM)", "U.(RM)",
]

MONETARY_RE = re.compile(r"(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.])")


def canonicalize(line: str) -> str:
    s = line.upper()
    s = re.sub(r"\s+", " ", s).strip()
    return s


def contains_any(canon: str, needles) -> bool:
    return any(n in canon for n in needles)


def parse_amount(text: str):
    matches = MONETARY_RE.findall(text)
    if not matches:
        return None
    last = matches[-1].replace(",", "")
    try:
        val = float(last)
    except ValueError:
        return None
    return f"{val:.2f}"


def find_total(ocr_text: str):
    """Return (tier_rank, amount_str) or None using keyword priority rules."""
    raw_lines = [ln for ln in ocr_text.split("\n") if ln.strip()]
    canon_lines = [canonicalize(ln) for ln in raw_lines]

    # Detect start of GST/TAX summary section; lines after are ineligible.
    cutoff = len(raw_lines)
    summary_re = re.compile(r"\b(GST|TAX|SST)\s*SUMMARY\b")
    for i, c in enumerate(canon_lines):
        if summary_re.search(c):
            cutoff = i
            break

    for tier_rank, (_, keywords) in enumerate(TIERS):
        candidates = []
        for i in range(cutoff):
            canon = canon_lines[i]
            if not any(k in canon for k in keywords):
                continue
            if contains_any(canon, EXCLUSION_KEYWORDS):
                continue
            if contains_any(canon, COLUMN_HEADER_TOKENS):
                continue
            candidates.append(i)

        # Iterate last-to-first.
        for i in reversed(candidates):
            amt = parse_amount(raw_lines[i])
            if amt is not None:
                return (tier_rank, amt)
            # Split-line fallback: only if this line contains ZERO digits.
            if not re.search(r"\d", raw_lines[i]):
                # Check next non-empty eligible line.
                for j in range(i + 1, cutoff):
                    nxt_canon = canon_lines[j]
                    if contains_any(nxt_canon, EXCLUSION_KEYWORDS):
                        continue
                    if contains_any(nxt_canon, ["CASH", "VISA", "MASTER", "CARD",
                                                 "CREDIT", "DEBIT", "PAYMENT",
                                                 "TENDERED", "PAID", "RECEIVED"]):
                        continue
                    amt = parse_amount(raw_lines[j])
                    if amt is not None:
                        return (tier_rank, amt)
                    break
    return None


DATE_PATTERNS = [
    # DD/MM/YYYY or DD-MM-YYYY (also DD.MM.YYYY)
    re.compile(r"\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})\b"),
    # DD/MM/YY or DD-MM-YY
    re.compile(r"\b(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})\b"),
]


def parse_date_from_line(line: str):
    for pat in DATE_PATTERNS:
        for m in pat.finditer(line):
            d, mo, y = m.group(1), m.group(2), m.group(3)
            try:
                di, mi = int(d), int(mo)
                yi = int(y)
            except ValueError:
                continue
            if yi < 100:
                yi += 2000
            if 1 <= di <= 31 and 1 <= mi <= 12 and 2000 <= yi <= 2099:
                return f"{yi:04d}-{mi:02d}-{di:02d}"
    return None


def find_date(ocr_text: str):
    """Pick the best date, preferring lines labeled with DATE."""
    raw_lines = [ln for ln in ocr_text.split("\n") if ln.strip()]
    labeled = []
    unlabeled = []
    for line in raw_lines:
        c = line.upper()
        d = parse_date_from_line(line)
        if d is None:
            continue
        # Skip "Print Date" lines
        if "PRINT DATE" in c or "PRINT TIME" in c:
            continue
        if re.search(r"\bDATE\b", c) or re.search(r"\bDATA\b", c) or re.search(r"\bDAIE\b", c):
            labeled.append(d)
        else:
            unlabeled.append(d)
    if labeled:
        return labeled[0]
    if unlabeled:
        return unlabeled[0]
    return None


def ocr_variants(image_path: Path):
