    img = Image.open(image_path).convert("RGB")
    gray = ImageOps.grayscale(img)
    gray_ac = ImageOps.autocontrast(gray)

    w, h = gray_ac.size
    gray_2x = gray_ac.resize((w * 2, h * 2), Image.LANCZOS)
    gray_3x = gray_ac.resize((w * 3, h * 3), Image.LANCZOS)

    cfgs = [
        ("1x_psm6", gray_ac, "--psm 6"),
        ("1x_psm4", gray_ac, "--psm 4"),
        ("2x_psm6", gray_2x, "--psm 6"),
        ("2x_psm4", gray_2x, "--psm 4"),
        ("3x_psm6", gray_3x, "--psm 6"),
    ]
    out = {}
    for name, im, cfg in cfgs:
        try:
            out[name] = pytesseract.image_to_string(im, config=cfg)
        except Exception:
            out[name] = ""
    return out


def extract_fields(image_path: Path):
    variants = ocr_variants(image_path)

    # Total: collect (tier, amount) tuples across variants, then pick best tier,
    # breaking ties by frequency.
    totals = []
    for text in variants.values():
        res = find_total(text)
        if res is not None:
            totals.append(res)

    total_str = None
    if totals:
        best_tier = min(t for t, _ in totals)
        tier_amounts = [a for t, a in totals if t == best_tier]
        counter = Counter(tier_amounts)
        total_str = counter.most_common(1)[0][0]

    # Date: pick most frequent valid date across variants.
    dates = []
    for text in variants.values():
        d = find_date(text)
        if d:
            dates.append(d)
    date_str = Counter(dates).most_common(1)[0][0] if dates else None

    return date_str, total_str


def main():
    rows = []
    for fname in sorted(os.listdir(IMG_DIR)):
        path = IMG_DIR / fname
        if not path.is_file():
            continue
        date_str, total_str = extract_fields(path)
        rows.append((fname, date_str, total_str))
        print(f"{fname}\tdate={date_str}\ttotal={total_str}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fname, d, t in rows:
        ws.append([fname, d, t])
    wb.save(OUT_XLSX)
    print(f"\nSaved {OUT_XLSX}")


if __name__ == "__main__":
    main()
