    for fname in sorted(os.listdir(IMG_DIR)):
        path = IMG_DIR / fname
        if not path.is_file():
            continue
        date_str, total_str = extract_fields(path)
        rows.append((fname, date_str, total_str))
        print(f"{fname}\tdate={date_str}\ttotal={total_str}")

    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for fname, d, t in rows:
        ws.append([fname, d, t])
