    "U/(RM)", "U(RM)", "U.(RM)",
]

# Tax-disclosure pattern: "N% GST/TAX/SST ... amount" — amount is the tax,
# not the total. Example: "TOTAL INCLUDES 6% GST 0.48".
TAX_DISCLOSURE_RE = re.compile(r"\d+\s*%\s*(GST|TAX|SST)", re.IGNORECASE)

